const rows = $input.all().map(i => i.json);
if (!rows.length) return [];
const byBureau = {};
for (const r of rows) (byBureau[r.bureau] = byBureau[r.bureau] || []).push(r);
return Object.entries(byBureau).map(([bureau, items]) => ({ json: {
  case_id: items[0].case_id, bureau, round: items[0].round,
  consumer: { first_name: items[0].first_name, last_name: items[0].last_name,
    street: items[0].street, city: items[0].city, state: items[0].state,
    zip: items[0].zip, ssn_last4: items[0].ssn_last4 }, items } }));

const d = $input.first().json;
const roundGuide = {
  1: 'Round 1: a clear factual dispute under 15 U.S.C. 1681i.',
  2: 'Round 2: a Method of Verification request under 1681i(a)(7).',
  3: 'Round 3: procedural escalation citing 1681s-2(b).'
};
const system = 'You draft FCRA dispute letters for a licensed credit-repair service. Rules: only assert supported facts, no false statements, no outcome guarantees, cite statute by section. Output ONLY the letter body text.';
const user = (roundGuide[d.round] || roundGuide[1]) + '\n\nBureau: ' + d.bureau + '\nConsumer: ' + JSON.stringify(d.consumer) + '\nItems: ' + JSON.stringify(d.items, null, 2);
return [{ json: { ...d, anthropic_request: { model: 'claude-sonnet-4-6', max_tokens: 2048, system, messages: [{ role: 'user', content: user }] } } }];

const resp = $input.first().json;
const d = $('Build Letter Prompt').first().json;
const body = (resp.content && resp.content[0] && resp.content[0].text) || '';
const banned = [/guarantee/i, /erase your debt/i, /new credit identity/i, /CPN/i, /will raise your score/i];
const violations = banned.filter(rx => rx.test(body)).map(String);
const passed = violations.length === 0 && /1681/.test(body) && body.length > 200;
return [{ json: { case_id: d.case_id, bureau: d.bureau, round: d.round, letter_body: body,
  item_ids: d.items.map(i => i.item_id), lint_passed: passed, lint_violations: violations,
  letter_status: passed ? 'pending_review' : 'needs_rewrite' } }];
